pub(crate) fn read8(address: u64) -> Option<u8> {
    let rva = address.checked_sub(super::end_final4_core::LIB_BASE)? as u32;
    if rva < 0x1000 {
        for &(start, bytes) in ZERO_PAGE_RANGES {
            if rva >= start && rva - start < bytes.len() as u32 {
                return Some(bytes[(rva - start) as usize]);
            }
        }
        return None;
    }
    let page = rva & !0xfff;
    let offset = (rva & 0xfff) as usize;
    let table: &[u8; 4096] = match page {
        0x01000 => &PAGE_01000,
        0x03000 => &PAGE_03000,
        0x06000 => &PAGE_06000,
        0x48000 => &PAGE_48000,
        _ => return None,
    };
    Some(table[offset])
}
